export const RATES = {
  2003:46, 2004:45, 2005:44, 2006:45, 2007:41, 2008:43, 2009:48, 2010:45.7,
  2011:46.7, 2012:53.4, 2013:58.6, 2014:61, 2015:64, 2016:67, 2017:65,
  2018:68, 2019:70, 2020:74.1, 2021:74, 2022:78.6, 2023:82.6, 2024:83.4,
  2025:85, 2026:86,
};
export function usd(inr, year) { if (inr == null) return null; const r = RATES[year] || RATES[2026]; return inr / r; }
export function fmtINR(n) {
  if (n == null) return null;
  if (n >= 10000000) return '\u20b9' + (n / 10000000).toFixed(2).replace(/\.00$/, '') + ' crore';
  if (n >= 100000) return '\u20b9' + (n / 100000).toFixed(2).replace(/\.00$/, '') + ' lakh';
  return '\u20b9' + n.toLocaleString('en-IN');
}

export function fmtUSD(n) {
  if (n == null) return null;
  if (n >= 1000000) return '$' + (n / 1000000).toFixed(2).replace(/\.00$/, '') + 'M';
  if (n >= 1000) return '$' + (n / 1000).toFixed(1).replace(/\.0$/, '') + 'K';
  return '$' + Math.round(n).toLocaleString('en-US');
}

